1: import { useCallback, useEffect, useRef, useState } from 'react';
2: import { useLocation, useNavigate, useParams } from 'react-router-dom';
3: import { AlertCircle, RotateCw } from 'lucide-react';
4: import { MessageStream } from '@/components/chat/MessageStream';
5: import { InputPill } from '@/components/chat/InputPill';
6: import { ThinkingCapsule } from '@/components/chat/ThinkingCapsule';
7: import { useCardTitles } from '@/lib/suggestions';
8: import { useAgentChat, useCreateSession, useMessages, useSessions } from '@/queries/chat';
9: 
10: interface ChatLocationState {
11:   seed?: string;
12:   cardId?: string;
13: }
14: 
15: export default function ChatRoute() {
16:   const { sessionId: routeSessionId } = useParams<{ sessionId: string }>();
17:   const location = useLocation();
18:   const navigate = useNavigate();
19: 
20:   const state = (location.state ?? {}) as ChatLocationState;
21:   const [seed, setSeed] = useState<string | undefined>(state.seed);
22:   const [createdSessionId, setCreatedSessionId] = useState<string | null>(null);
23: 
24:   const sessions = useSessions();
25:   const createSession = useCreateSession();
26:   const creatingRef = useRef(false);
27:   const suggestions = useCardTitles(3);
28: 
29:   const activeSessionId =
30:     routeSessionId ?? createdSessionId ?? sessions.data?.[0]?.session_id ?? null;
31: 
32:   const messagesQuery = useMessages(activeSessionId);
33:   const chat = useAgentChat(activeSessionId);
34: 
35:   // A first-run user with no sessions gets one, silently.
36:   useEffect(() => {
37:     if (routeSessionId || createdSessionId) return;
38:     if (!sessions.data || sessions.data.length > 0) return;
39:     if (creatingRef.current) return;
40: 
41:     creatingRef.current = true;
42:     createSession.mutate(
43:       { title: undefined, scope: 'chat:create-session' },
44:       { onSuccess: (session) => setCreatedSessionId(session.session_id) },
45:     );
46:   }, [routeSessionId, createdSessionId, sessions.data, createSession]);
47: 
48:   const handleSeedConsumed = useCallback(() => {
49:     setSeed(undefined);
50:     if (state.cardId) navigate('/agent/chat', { replace: true, state: null });
51:   }, [navigate, state.cardId]);
52: 
53:   const messages = messagesQuery.data ?? [];
54:   const showThinking = chat.streaming;
55:   // The empty hint only renders once the history query has settled: while loading, an empty
56:   // array means "not fetched yet", and painting EmptyChat then displaces real history in a
57:   // visible flash when the query resolves.
58:   const historySettled = messagesQuery.isSuccess || messagesQuery.isError;
59: 
60:   return (
61:     <div className="flex h-dvh flex-col">
62:       <div className="min-h-0 flex-1">
63:         <MessageStream
64:           messages={messages}
65:           streamedText={chat.streamedText}
66:           streaming={chat.streaming}
67:           trailing={
68:             showThinking && !chat.awaitingApproval ? (
69:               <ThinkingCapsule
70:                 active
71:                 steps={chat.steps}
72:               />
73:             ) : null
74:           }
75:           emptyHint={
76:             historySettled ? <EmptyChat suggestions={suggestions} onPick={chat.send} /> : null
77:           }
78:         />
79:       </div>
80: 
81:       {chat.connection === 'reconnecting' ? (
82:         <div className="pointer-events-none fixed inset-x-0 bottom-[11.5rem] z-20 flex justify-center px-4 md:bottom-[7.5rem] md:pl-20">
83:           <p className="glass inline-flex items-center gap-2 rounded-[8px] px-3.5 py-2 text-[12px] text-[var(--text-muted)]">
84:             <RotateCw size={13} strokeWidth={1.5} className="animate-spin" />
85:             Reconnecting to Vigil...
86:           </p>
87:         </div>
88:       ) : null}
89: 
90:       {chat.awaitingApproval ? (
91:         <div className="pointer-events-auto fixed inset-x-0 bottom-[11.5rem] z-20 flex justify-center px-4 md:bottom-[7.5rem] md:pl-20">
92:           <button
93:             type="button"
94:             onClick={() => navigate('/agent/approvals')}
95:             className="glass cursor-pointer rounded-[8px] px-3.5 py-2 text-[12px] text-[var(--text-muted)] transition-colors hover:text-[var(--text)]"
96:           >
97:             The agent is waiting on your approval, open Approvals to decide
98:           </button>
99:         </div>
100:       ) : null}
101: 
102:       {chat.error ? (
103:         <div className="pointer-events-none fixed inset-x-0 bottom-[11.5rem] z-20 flex justify-center px-4 md:bottom-[10rem] md:pl-20">
104:           <p className="glass inline-flex max-w-md items-center gap-2 rounded-[8px] px-3.5 py-2 text-[12px] text-[var(--text)]">
105:             <AlertCircle size={13} strokeWidth={1.5} />
106:             {chat.error}
107:           </p>
108:         </div>
109:       ) : null}
110: 
111:       <InputPill
112:         onSend={chat.send}
113:         onStop={chat.stop}
114:         streaming={chat.streaming}
115:         hasReplyTokens={chat.steps.length > 0}
116:         disabled={!activeSessionId}
117:         {...(seed ? { seed } : {})}
118:         onSeedConsumed={handleSeedConsumed}
119:       />
120:     </div>
121:   );
122: }
123: 
124: function EmptyChat({
125:   suggestions,
126:   onPick,
127: }: {
128:   suggestions: string[];
129:   onPick: (text: string) => void;
130: }) {
131:   return (
132:     <div className="animate-rise flex flex-col items-center px-4 pt-8 text-center">
133:       <h1 className="text-[26px] font-semibold tracking-[-0.03em]">
134:         What are we working on?
135:       </h1>
136:       <p className="mt-2 max-w-sm text-[15px] leading-relaxed text-[var(--text-muted)]">
137:         Ask anything, or hand Vigil a task it can run end to end.
138:       </p>
139: 
140:       {suggestions.length > 0 ? (
141:         <ul className="mt-8 w-full max-w-md space-y-2">
142:           {suggestions.map((suggestion) => (
143:             <li key={suggestion}>
144:               <button
145:                 type="button"
146:                 onClick={() => onPick(suggestion)}
147:                 className="card w-full rounded-[10px] px-4 py-3 text-left text-[14px] text-[var(--text)] transition-colors"
148:               >
149:                 {suggestion}
150:               </button>
151:             </li>
152:           ))}
153:         </ul>
154:       ) : null}
155:     </div>
156:   );
157: }

