1: import { useEffect, useMemo, useRef } from 'react';
2: import { motion } from 'framer-motion';
3: import type { ReactNode } from 'react';
4: import type { StreamMessage } from '@/types';
5: import MessageItem from './MessageItem';
6: import {
7:   Message,
8: } from '@/components/ui/c-message-3-utils/message';
9: import { Bubble, BubbleContent } from '@/components/ui/c-message-3-utils/bubble';
10: 
11: /** Overshoot spring shared with MessageItem so the reply lands in step. */
12: const enterSpring = {
13:   type: 'spring' as const,
14:   stiffness: 480,
15:   damping: 20,
16:   mass: 0.9,
17: };
18: 
19: interface Props {
20:   messages: StreamMessage[];
21:   streamedText: string;
22:   streaming: boolean;
23:   trailing?: ReactNode;
24:   emptyHint: ReactNode;
25: }
26: 
27: const STICK_THRESHOLD = 80;
28: 
29: function dayLabel(iso: string): string {
30:   const d = new Date(iso);
31:   return d.toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' });
32: }
33: 
34: export function MessageStream({ messages, streamedText, streaming, trailing, emptyHint }: Props) {
35:   const endRef = useRef<HTMLDivElement>(null);
36:   const scrollerRef = useRef<HTMLDivElement>(null);
37:   const stickRef = useRef(true);
38:   // Message ids that have already rendered. The first batch ever seen gets a
39:   // stagger; everything appended later (sends, streaming) enters immediately.
40:   const seenRef = useRef<Set<string>>(new Set());
41:   const staggers = useMemo(() => {
42:     const coldStart = seenRef.current.size === 0;
43:     return messages.map((m, i) => {
44:       const fresh = !seenRef.current.has(m.id);
45:       seenRef.current.add(m.id);
46:       return fresh && coldStart && i < 8 ? i : 0;
47:     });
48:   }, [messages]);
49: 
50:   // A divider whenever the calendar day changes, matching the brief separators in the design.
51:   const dividers = useMemo(() => {
52:     const out: (string | undefined)[] = [];
53:     let previous: string | null = null;
54:     for (const m of messages) {
55:       const day = dayLabel(m.created_at);
56:       out.push(day !== previous ? day : undefined);
57:       previous = day;
58:     }
59:     return out;
60:   }, [messages]);
61: 
62:   useEffect(() => {
63:     const node = scrollerRef.current;
64:     if (!node) return;
65:     const onScroll = () => {
66:       stickRef.current = node.scrollHeight - node.scrollTop - node.clientHeight < STICK_THRESHOLD;
67:     };
68:     node.addEventListener('scroll', onScroll, { passive: true });
69:     return () => node.removeEventListener('scroll', onScroll);
70:   }, []);
71: 
72:   useEffect(() => {
73:     if (!stickRef.current) return;
74:     endRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' });
75:   }, [messages.length, streamedText]);
76: 
77:   const isEmpty = messages.length === 0 && !streaming;
78: 
79:   return (
80:     <div ref={scrollerRef} className="scroll-soft h-full overflow-y-auto">
81:       <div className="mx-auto w-full max-w-3xl space-y-8 px-6 pb-48 pt-24 md:pl-24 md:pr-6 md:pt-28">
82:         {isEmpty ? emptyHint : null}
83: 
84:         <ul className="space-y-8" aria-live="polite" aria-relevant="additions text" aria-busy={streaming}>
85:           {messages.map((message, i) => (
86:             <li key={message.id} className="group">
87:               <MessageItem message={message} divider={dividers[i]} staggerIndex={staggers[i]} />
88:             </li>
89:           ))}
90: 
91:           {streaming && streamedText ? (
92:             <li>
93:               <motion.div initial={{ opacity: 0, y: 18 }} animate={{ opacity: 1, y: 0 }} transition={enterSpring}>
94:                 <Message>
95:                   <motion.div
96:                     initial={{ scale: 0.82 }}
97:                     animate={{ scale: 1 }}
98:                     transition={{ ...enterSpring, delay: 0.06 }}
99:                     style={{ transformOrigin: 'top left' }}
100:                   >
101:                     <Bubble variant="muted">
102:                       <motion.div
103:                         initial={{ opacity: 0, y: 6 }}
104:                         animate={{ opacity: 1, y: 0 }}
105:                         transition={{ duration: 0.45, delay: 0.18, ease: 'easeOut' }}
106:                       >
107:                         <BubbleContent>
108:                           {streamedText}
109:                           <span
110:                             aria-hidden
111:                             className="ml-0.5 inline-block h-[1.05em] w-[2px] translate-y-[3px] animate-pulse bg-[var(--text)]"
112:                           />
113:                         </BubbleContent>
114:                       </motion.div>
115:                     </Bubble>
116:                   </motion.div>
117:                 </Message>
118:               </motion.div>
119:             </li>
120:           ) : null}
121:         </ul>
122: 
123:         {trailing ? <div className="mt-6">{trailing}</div> : null}
124: 
125:         <div ref={endRef} />
126:       </div>
127:     </div>
128:   );
129: }
130: 
131: export default MessageStream;

