63: interface MarkdownContentProps {
64:   content: string;
65:   className?: string;
66: }
67: 
68: export function MarkdownContent({ content, className = '' }: MarkdownContentProps) {
69:   return (
70:     <div className={`break-words ${className}`}>
71:       <ReactMarkdown
72:         components={{
73:           code({ className: codeClass, children, ...props }) {
74:             const match = /language-(\w+)/.exec(codeClass || '');
75:             const raw = String(children ?? '');
