203: export function ThinkingCapsule({ active, steps = [], summary }: Props) {
204:   const [open, setOpen] = useState(false);
205:   if (!active && steps.length === 0) return null;
206: 
207:   // Filter out streaming delta chunks from the semantic timeline
208:   const semanticSteps = steps.filter((s) => s.event_type !== 'message_delta');
209:   const latestStep = semanticSteps[semanticSteps.length - 1];
210: 
211:   let displaySummary = summary;
212:   if (!displaySummary) {
213:     if (active) {
214:       if (latestStep?.event_type === 'tool_call') {
215:         const tool = String(latestStep.payload.tool_name ?? 'tool');
216:         displaySummary = `Running ${tool}...`;
217:       } else if (latestStep?.event_type === 'tool_result') {
218:         displaySummary = 'Processing tool results...';
219:       } else {
220:         displaySummary = semanticSteps.length > 0 ? `Thinking & executing (${semanticSteps.length} steps)...` : 'Thinking it through...';
221:       }
222:     } else {
223:       displaySummary = `Completed execution (${semanticSteps.length} steps)`;
224:     }
225:   }
226: 
227:   return (
228:     <div className="mb-4" role="status">
