42: /* -------------------------------------------------------------------------------------------
43:    The chat transport. A sent message IS one agent run: the message posts to POST /runs against
44:    the server's default agent config, ThinkingCapsule renders the run's step events, and the
45:    reply arrives in the run_completed frame payload (`{"content": ...}`,
46:    backend/src/modules/runs/loop.py). Stop posts POST /runs/{id}/cancel. History persists
47:    server-side: run messages carry the thread, GET /chat/sessions/{id}/messages returns the
48:    user prompts and assistant replies of the whole conversation.
49:    ------------------------------------------------------------------------------------------- */
50: 
51: export interface AgentChat {
52:   /** True while the head run is queued, running, awaiting approval or a background job. */
53:   streaming: boolean;
54:   /** Always empty: the agent reply arrives as a completed run, not token frames. */
55:   streamedText: string;
56:   connection: StreamState;
57:   error: string | null;
58:   /** Step events of the active run, oldest first, fed straight to the ThinkingCapsule. */
59:   steps: RunStepEvent[];
60:   /** True when the run parked on an approval, the Approvals page holds the decision. */
61:   awaitingApproval: boolean;
62:   lastPrompt: string | null;
63:   send: (prompt: string) => void;
64:   retry: () => void;
65:   stop: () => void;
66: }
67: 
68: /**
69:  * One chat turn = one run. Each send has its own prompt and its own run; multi-turn context
70:  * replays like the CLI harness performs are a backend feature, not yet over HTTP, so every
71:  * turn stands alone.
72:  */
73: export function useAgentChat(sessionId: string | null): AgentChat {
