199:         if (optimisticId) clearOptimisticFlag(optimisticId);
200:       } else if (optimisticId && target) {
201:         queryClient.setQueryData<StreamMessage[]>(messagesKey(target), (current) =>
202:           current
203:             ? current.map((m) =>
204:                 m.id === optimisticId
205:                   ? { ...m, local_state: 'failed', failure_class: 'network', failure_reason: reason }
206:                   : m,
207:               )
208:             : current,
209:         );
210:       }
211:     }
212:     optimisticIdRef.current = null;
213:   }, [activeRunId, finalisedRunId, steps, run, queryClient, clearOptimisticFlag]);
214: 
215:   const send = useCallback(
216:     (prompt: string) => {
217:       const trimmed = prompt.trim();
218:       const target = sessionIdRef.current;
219:       if (!trimmed || !target) return;
220: 
221:       const configId = defaultConfig.data?.id;
222:       if (!configId) {
223:         setError('The agent configuration is not ready yet. Try again in a moment.');
224:         return;
225:       }
226: 
227:       const localId = `local-user-${Date.now()}`;
228:       optimisticIdRef.current = localId;
229:       setLastPrompt(trimmed);
230:       setError(null);
231:       queryClient.setQueryData<StreamMessage[]>(messagesKey(target), (current) => {
232:         const optimistic: StreamMessage = {
233:           id: localId,
234:           session_id: target,
235:           role: 'user',
236:           content: trimmed,
237:           created_at: new Date().toISOString(),
238:           local_state: 'sending',
239:         };
240:         return current ? [...current, optimistic] : [optimistic];
241:       });
242: 
243:       void api
244:         .createRun(
245:           {
246:             config_id: configId,
247:             session_id: target,
248:             initial_prompt: trimmed,
249:           },
250:           `chat:send:${target}:${Date.now()}`,
251:         )
252:         .then((run: Run) => {
253:           setActiveRunId(run.id);
254:           queryClient.setQueryData(runKey(run.id), run);
255:           if (optimisticIdRef.current) {
256:             clearOptimisticFlag(optimisticIdRef.current);
257:           }
258:         })
259:         .catch((cause: unknown) => {
260:           optimisticIdRef.current = null;
261:           if (target) {
262:             const reason = userMessageOf(cause);
263:             queryClient.setQueryData<StreamMessage[]>(messagesKey(target), (current) =>
264:               current
265:                 ? current.map((m) =>
266:                     m.id === localId
267:                       ? { ...m, local_state: 'failed', failure_class: 'network', failure_reason: reason }
268:                       : m,
269:                   )
270:                 : current,
271:             );
272:           }
273:           setError(userMessageOf(cause));
274:         });
275:     },
276:     [defaultConfig.data, queryClient, clearOptimisticFlag],
277:   );
278: 
279:   const stop = useCallback(() => {
280:     if (!activeRunId) return;
281:     cancelRunMutation.mutate({ runId: activeRunId, scope: `run:cancel:${activeRunId}` });
282:   }, [activeRunId, cancelRunMutation]);
283: 
284:   const retry = useCallback(() => {
285:     if (lastPrompt) send(lastPrompt);
286:   }, [lastPrompt, send]);
287: 
288:   return {
289:     streaming,
290:     streamedText,
291:     connection: subscription.connection,
292:     error,
293:     steps,
294:     awaitingApproval,
295:     lastPrompt,
296:     send,
297:     retry,
298:     stop,
299:   };
300: }

