import { useState } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import remarkMath from 'remark-math';
import rehypeKatex from 'rehype-katex';
import 'katex/dist/katex.min.css';
import { Check, Copy, ArrowUpRight, Terminal, FileCode2 } from 'lucide-react';

interface CodeBlockProps {
  language: string;
  code: string;
}

export function CodeBlock({ language, code }: CodeBlockProps) {
  const [copied, setCopied] = useState(false);

  const lines = code.split('\n');
  const lineCount = lines.length;
  const isShell = ['bash', 'sh', 'zsh', 'shell', 'console', 'terminal'].includes(
    language.toLowerCase(),
  );

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      const textarea = document.createElement('textarea');
      textarea.value = code;
      document.body.appendChild(textarea);
      textarea.select();
      document.execCommand('copy');
      document.body.removeChild(textarea);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <div className="my-4 w-full max-w-full min-w-0 overflow-hidden rounded-[14px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_3%,transparent)] p-1 shadow-sm">
      <div className="overflow-hidden rounded-[10px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-solid)_82%,transparent)]">
        <div className="flex items-center justify-between border-b border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_4%,transparent)] px-3.5 py-2">
          <div className="flex items-center gap-2 min-w-0">
            {isShell ? (
              <Terminal size={13} strokeWidth={1.6} className="shrink-0 text-sky-400" />
            ) : (
              <FileCode2 size={13} strokeWidth={1.6} className="shrink-0 text-[var(--text-muted)]" />
            )}
            <span className="truncate font-mono text-[11px] font-semibold uppercase tracking-[0.08em] text-[var(--text)]">
              {language || 'text'}
            </span>
            {lineCount > 1 ? (
              <span className="rounded-full bg-[color-mix(in_srgb,var(--text)_7%,transparent)] px-2 py-0.5 font-mono text-[10px] tabular-nums text-[var(--text-muted)]">
                {lineCount} lines
              </span>
            ) : null}
          </div>

          <button
            type="button"
            onClick={handleCopy}
            aria-label={copied ? 'Copied code' : 'Copy code to clipboard'}
            className="inline-flex shrink-0 cursor-pointer items-center gap-1.5 rounded-[7px] border border-transparent px-2.5 py-1 text-[11px] font-medium text-[var(--text-muted)] transition-all duration-150 hover:border-[var(--border)] hover:bg-[color-mix(in_srgb,var(--text)_8%,transparent)] hover:text-[var(--text)] active:scale-95"
          >
            {copied ? (
              <>
                <Check size={12} strokeWidth={2} className="text-emerald-400" />
                <span className="text-emerald-400">Copied</span>
              </>
            ) : (
              <>
                <Copy size={12} strokeWidth={1.5} />
                <span>Copy</span>
              </>
            )}
          </button>
        </div>

        <pre className="scroll-soft max-w-full overflow-x-auto p-3.5 font-mono text-[13px] leading-[1.65] text-[var(--text)]">
          <code className="block min-w-0">{code}</code>
        </pre>
      </div>
    </div>
  );
}

interface MarkdownContentProps {
  content: string;
  className?: string;
}

export function MarkdownContent({ content, className = '' }: MarkdownContentProps) {
  return (
    <div
      className={`w-full max-w-full min-w-0 text-[15px] leading-[1.7] text-[var(--text)] [overflow-wrap:anywhere] ${className}`}
    >
      <ReactMarkdown
        remarkPlugins={[remarkGfm, remarkMath]}
        rehypePlugins={[rehypeKatex]}
        components={{
          code({ className: codeClass, children, ...props }) {
            const match = /language-([\w-]+)/.exec(codeClass || '');
            const raw = String(children ?? '');
            const isBlock = Boolean(match) || raw.includes('\n');
            if (isBlock) {
              const codeString = raw.replace(/\n$/, '');
              return <CodeBlock language={match?.[1] ?? ''} code={codeString} />;
            }
            return (
              <code
                className="rounded-[6px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_7%,transparent)] px-1.5 py-0.5 font-mono text-[0.86em] font-medium text-[var(--text)] [overflow-wrap:anywhere]"
                {...props}
              >
                {children}
              </code>
            );
          },
          pre({ children }) {
            return <>{children}</>;
          },
          p({ children }) {
            return <p className="mb-3.5 last:mb-0 leading-[1.72] [overflow-wrap:anywhere]">{children}</p>;
          },
          ul({ children }) {
            return (
              <ul className="mb-3.5 last:mb-0 list-disc space-y-1.5 pl-5 marker:text-[var(--text-muted)]">
                {children}
              </ul>
            );
          },
          ol({ children }) {
            return (
              <ol className="mb-3.5 last:mb-0 list-decimal space-y-1.5 pl-5 marker:font-medium marker:text-[var(--text-muted)]">
                {children}
              </ol>
            );
          },
          li({ children }) {
            return <li className="leading-[1.68] pl-0.5 [overflow-wrap:anywhere]">{children}</li>;
          },
          h1({ children }) {
            return (
              <h1 className="mb-3 mt-6 first:mt-0 text-[1.35em] font-semibold tracking-[-0.02em] text-[var(--text)]">
                {children}
              </h1>
            );
          },
          h2({ children }) {
            return (
              <h2 className="mb-2.5 mt-5 first:mt-0 border-b border-[var(--border)] pb-1.5 text-[1.18em] font-semibold tracking-[-0.015em] text-[var(--text)]">
                {children}
              </h2>
            );
          },
          h3({ children }) {
            return (
              <h3 className="mb-2 mt-4 first:mt-0 text-[1.06em] font-semibold tracking-[-0.01em] text-[var(--text)]">
                {children}
              </h3>
            );
          },
          h4({ children }) {
            return (
              <h4 className="mb-1.5 mt-3 first:mt-0 text-[0.96em] font-semibold uppercase tracking-[0.04em] text-[var(--text-muted)]">
                {children}
              </h4>
            );
          },
          blockquote({ children }) {
            return (
              <blockquote className="my-3.5 rounded-r-[10px] border-l-[3px] border-[var(--border-strong)] bg-[color-mix(in_srgb,var(--text)_3.5%,transparent)] py-2.5 pl-4 pr-3 text-[0.96em] text-[var(--text-muted)]">
                {children}
              </blockquote>
            );
          },
          hr() {
            return <hr className="my-5 border-0 border-t border-[var(--border)]" />;
          },
          a({ href, children }) {
            const isExternal = Boolean(href && /^https?:\/\//i.test(href));
            return (
              <a
                href={href}
                target={isExternal ? '_blank' : undefined}
                rel={isExternal ? 'noreferrer noopener' : undefined}
                className="inline-flex items-baseline gap-0.5 font-medium text-[var(--text)] underline decoration-[var(--border-strong)] underline-offset-4 transition-colors hover:decoration-[var(--text)]"
              >
                <span className="[overflow-wrap:anywhere]">{children}</span>
                {isExternal ? (
                  <ArrowUpRight
                    size={12}
                    strokeWidth={1.75}
                    className="inline-block shrink-0 translate-y-[1px] text-[var(--text-muted)]"
                  />
                ) : null}
              </a>
            );
          },
          table({ children }) {
            return (
              <div className="my-4 w-full max-w-full overflow-hidden rounded-[12px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_2.5%,transparent)] shadow-xs">
                <div className="scroll-soft max-w-full overflow-x-auto">
                  <table className="w-full border-collapse text-left text-[13.5px] tabular-nums">
                    {children}
                  </table>
                </div>
              </div>
            );
          },
          thead({ children }) {
            return (
              <thead className="border-b border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_5%,transparent)]">
                {children}
              </thead>
            );
          },
          th({ children }) {
            return (
              <th className="px-3.5 py-2.5 text-left text-[11.5px] font-semibold uppercase tracking-[0.06em] text-[var(--text)]">
                {children}
              </th>
            );
          },
          td({ children }) {
            return (
              <td className="border-t border-[var(--border)] px-3.5 py-2.5 align-top text-[var(--text-muted)] [overflow-wrap:anywhere]">
                {children}
              </td>
            );
          },
          strong({ children }) {
            return <strong className="font-semibold text-[var(--text)]">{children}</strong>;
          },
          input({ type, checked, ...props }) {
            if (type === 'checkbox') {
              return (
                <input
                  type="checkbox"
                  checked={checked}
                  readOnly
                  className="mr-2 h-3.5 w-3.5 translate-y-[1px] rounded accent-[var(--accent)]"
                  {...props}
                />
              );
            }
            return <input type={type} {...props} />;
          },
        }}
      >
        {content}
      </ReactMarkdown>
    </div>
  );
}

export default MarkdownContent;

import { useMemo, useState } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import {
  ChevronDown,
  Sparkles,
  Terminal,
  FileText,
  FileCode2,
  Globe,
  CheckCircle2,
  XCircle,
  ShieldAlert,
  Archive,
  RotateCw,
  FileDown,
  ListChecks,
  Puzzle,
  HelpCircle,
  Check,
  Copy,
  Mail,
  Calendar,
} from 'lucide-react';
import type { RunStepEvent } from '@/types';

interface Props {
  active: boolean;
  steps?: RunStepEvent[];
  summary?: string;
  defaultOpen?: boolean;
}

const spring = { type: 'spring' as const, stiffness: 400, damping: 30 };

interface PairedToolItem {
  kind: 'tool';
  id: string;
  stepNumber: number;
  toolName: string;
  arguments: Record<string, unknown>;
  partition?: string;
  resultStep?: RunStepEvent;
  createdAt: string;
}

interface SingleStepItem {
  kind: 'thought' | 'approval_required' | 'compaction';
  id: string;
  stepNumber: number;
  step: RunStepEvent;
  createdAt: string;
}

type TimelineItem = PairedToolItem | SingleStepItem;

function formatBytes(bytes: number): string {
  if (!Number.isFinite(bytes) || bytes < 0) return '';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
}

/**
 * Pair tool_call events with their corresponding tool_result events by tool_call_id
 * (or fallback to the earliest unpaired tool_call of the same tool_name), producing
 * a clean deck of cards instead of disconnected call/result rows.
 */
function buildTimeline(steps: RunStepEvent[]): TimelineItem[] {
  const items: TimelineItem[] = [];
  const toolIndexById = new Map<string, number>();
  const openToolIndicesByName = new Map<string, number[]>();

  for (let i = 0; i < steps.length; i += 1) {
    const step = steps[i];
    if (!step) continue;

    if (
      step.event_type === 'message_delta' ||
      step.event_type === 'run_completed' ||
      step.event_type === 'run_failed'
    ) {
      continue;
    }

    if (step.event_type === 'thought') {
      const content =
        typeof step.payload.content === 'string'
          ? step.payload.content.trim()
          : typeof step.payload.text === 'string'
            ? step.payload.text.trim()
            : '';
      const stage = typeof step.payload.stage === 'string' ? step.payload.stage : '';
      // Skip empty thoughts (e.g. pure tool-dispatch turns with no text reasoning)
      if (!content && stage !== 'compact_check') continue;

      items.push({
        kind: 'thought',
        id: `thought-${step.step_number}-${i}`,
        stepNumber: step.step_number,
        step,
        createdAt: step.created_at,
      });
      continue;
    }

    if (step.event_type === 'tool_call') {
      const callId =
        typeof step.payload.tool_call_id === 'string'
          ? step.payload.tool_call_id
          : `call-${step.step_number}-${i}`;
      const toolName = String(step.payload.tool_name ?? 'tool');
      const args =
        typeof step.payload.arguments === 'object' && step.payload.arguments !== null
          ? (step.payload.arguments as Record<string, unknown>)
          : {};
      const partition =
        typeof step.payload.partition === 'string' ? step.payload.partition : undefined;

      const idx = items.length;
      items.push({
        kind: 'tool',
        id: callId,
        stepNumber: step.step_number,
        toolName,
        arguments: args,
        partition,
        createdAt: step.created_at,
      });

      toolIndexById.set(callId, idx);
      const list = openToolIndicesByName.get(toolName) ?? [];
      list.push(idx);
      openToolIndicesByName.set(toolName, list);
      continue;
    }

    if (step.event_type === 'tool_result') {
      const callId =
        typeof step.payload.tool_call_id === 'string' ? step.payload.tool_call_id : null;
      const toolName = String(step.payload.tool_name ?? 'tool');

      let targetIdx: number | undefined =
        callId !== null ? toolIndexById.get(callId) : undefined;

      if (targetIdx === undefined) {
        const candidates = openToolIndicesByName.get(toolName);
        if (candidates && candidates.length > 0) {
          targetIdx = candidates.shift();
        }
      } else {
        const candidates = openToolIndicesByName.get(toolName);
        if (candidates) {
          const pos = candidates.indexOf(targetIdx);
          if (pos !== -1) candidates.splice(pos, 1);
        }
      }

      if (targetIdx !== undefined) {
        const existing = items[targetIdx];
        if (existing && existing.kind === 'tool') {
          existing.resultStep = step;
          continue;
        }
      }

      // Orphan tool_result fallback: create a synthetic paired item
      items.push({
        kind: 'tool',
        id: callId ?? `res-${step.step_number}-${i}`,
        stepNumber: step.step_number,
        toolName,
        arguments: {},
        resultStep: step,
        createdAt: step.created_at,
      });
      continue;
    }

    if (step.event_type === 'approval_required' || step.event_type === 'compaction') {
      items.push({
        kind: step.event_type,
        id: `${step.event_type}-${step.step_number}-${i}`,
        stepNumber: step.step_number,
        step,
        createdAt: step.created_at,
      });
    }
  }

  return items;
}

interface ParsedToolOutcome {
  completed: boolean;
  ok: boolean;
  errorText: string | null;
  content: unknown;
  artifactRef: string | null;
  rawResult: unknown;
}

function parseToolOutcome(resultStep?: RunStepEvent): ParsedToolOutcome {
  if (!resultStep) {
    return {
      completed: false,
      ok: true,
      errorText: null,
      content: null,
      artifactRef: null,
      rawResult: null,
    };
  }

  const payload = resultStep.payload;
  const raw = 'result' in payload ? payload.result : payload;

  if (typeof raw === 'object' && raw !== null) {
    const rec = raw as Record<string, unknown>;
    const hasOk = typeof rec.ok === 'boolean';
    const hasError = typeof rec.error === 'string' && rec.error.length > 0;
    const ok = hasOk ? Boolean(rec.ok) : !hasError;
    const errorText = hasError
      ? String(rec.error)
      : typeof rec.message === 'string' && !ok
        ? rec.message
        : null;
    const content = 'content' in rec ? rec.content : raw;
    const artifactRef = typeof rec.artifact_ref === 'string' ? rec.artifact_ref : null;
    return {
      completed: true,
      ok,
      errorText,
      content,
      artifactRef,
      rawResult: raw,
    };
  }

  const str = typeof raw === 'string' ? raw : JSON.stringify(raw);
  const isError = str.toLowerCase().startsWith('error:');
  return {
    completed: true,
    ok: !isError,
    errorText: isError ? str : null,
    content: str,
    artifactRef: null,
    rawResult: raw,
  };
}

function parseBashContent(content: unknown): {
  exitCode: number | null;
  stdout: string;
  stderr: string;
} {
  if (typeof content !== 'string') {
    if (typeof content === 'object' && content !== null) {
      const rec = content as Record<string, unknown>;
      return {
        exitCode: typeof rec.exit_code === 'number' ? rec.exit_code : null,
        stdout: typeof rec.stdout === 'string' ? rec.stdout : JSON.stringify(content, null, 2),
        stderr: typeof rec.stderr === 'string' ? rec.stderr : '',
      };
    }
    return { exitCode: null, stdout: '', stderr: '' };
  }

  const exitMatch = /^exit_code:\s*(-?\d+)\n/m.exec(content);
  const stdoutSplit = content.split('--- stdout ---\n');
  if (stdoutSplit.length > 1) {
    const afterStdout = stdoutSplit[1] ?? '';
    const stderrSplit = afterStdout.split('\n--- stderr ---\n');
    return {
      exitCode: exitMatch ? Number(exitMatch[1]) : null,
      stdout: (stderrSplit[0] ?? '').trimEnd(),
      stderr: (stderrSplit[1] ?? '').trimEnd(),
    };
  }

  return {
    exitCode: exitMatch ? Number(exitMatch[1]) : null,
    stdout: content.trimEnd(),
    stderr: '',
  };
}

function StatusPill({
  completed,
  ok,
  active,
  customLabel,
}: {
  completed: boolean;
  ok: boolean;
  active: boolean;
  customLabel?: string;
}) {
  if (!completed) {
    return (
      <span className="inline-flex shrink-0 items-center gap-1.5 rounded-full border border-sky-500/25 bg-sky-500/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-[0.06em] text-sky-400">
        {active ? <RotateCw size={10} strokeWidth={2} className="animate-spin" /> : null}
        {customLabel ?? 'Running'}
      </span>
    );
  }
  if (!ok) {
    return (
      <span className="inline-flex shrink-0 items-center gap-1 rounded-full border border-rose-500/25 bg-rose-500/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-[0.06em] text-rose-400">
        <XCircle size={11} strokeWidth={2} />
        {customLabel ?? 'Failed'}
      </span>
    );
  }
  return (
    <span className="inline-flex shrink-0 items-center gap-1 rounded-full border border-emerald-500/25 bg-emerald-500/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-[0.06em] text-emerald-400">
      <CheckCircle2 size={11} strokeWidth={2} />
      {customLabel ?? 'Done'}
    </span>
  );
}

