function CommandExecutionCard({
  item,
  active,
}: {
  item: PairedToolItem;
  active: boolean;
}) {
  const [expanded, setExpanded] = useState(false);
  const [copied, setCopied] = useState(false);
  const command = typeof item.arguments.command === 'string' ? item.arguments.command : '';
  const timeout =
    typeof item.arguments.timeout_seconds === 'number' ? item.arguments.timeout_seconds : null;

  const outcome = parseToolOutcome(item.resultStep);
  const parsed = parseBashContent(outcome.content);
  const hasOutput = Boolean(parsed.stdout || parsed.stderr || outcome.errorText);

  const handleCopyCommand = async () => {
    if (!command) return;
    try {
      await navigator.clipboard.writeText(command);
      setCopied(true);
      setTimeout(() => setCopied(false), 1800);
    } catch {
      // ignore
    }
  };

  return (
    <div className="w-full min-w-0 overflow-hidden rounded-[12px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-solid)_90%,transparent)] shadow-xs">
