          <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-[7px] bg-sky-500/12 text-sky-400">
            <Terminal size={13} strokeWidth={1.75} />
          </span>
          <span className="font-mono text-[11px] font-semibold uppercase tracking-[0.07em] text-[var(--text)]">
            Sandbox Shell
          </span>
          {parsed.exitCode !== null ? (
            <span
              className={`rounded px-1.5 py-0.5 font-mono text-[10px] tabular-nums ${
                parsed.exitCode === 0
                  ? 'bg-emerald-500/10 text-emerald-400'
                  : 'bg-rose-500/10 text-rose-400'
              }`}
            >
              exit {parsed.exitCode}
            </span>
          ) : timeout ? (
            <span className="font-mono text-[10px] text-[var(--text-muted)] tabular-nums">
              timeout {timeout}s
            </span>
          ) : null}
        </div>

        <div className="flex items-center gap-2 shrink-0">
          <StatusPill completed={outcome.completed} ok={outcome.ok} active={active} />
          {hasOutput ? (
            <button
              type="button"
              onClick={() => setExpanded((e) => !e)}
              className="inline-flex cursor-pointer items-center gap-1 rounded-[6px] px-2 py-0.5 text-[11px] font-medium text-[var(--text-muted)] transition-colors hover:bg-[color-mix(in_srgb,var(--text)_8%,transparent)] hover:text-[var(--text)]"
            >
              <span>{expanded ? 'Hide log' : 'Output'}</span>
              <ChevronDown
                size={12}
                className={`transition-transform duration-200 ${expanded ? 'rotate-180' : ''}`}
              />
            </button>
          ) : null}
        </div>
      </div>

      {/* Command Prompt Line */}
      <div className="flex items-start justify-between gap-2 bg-[color-mix(in_srgb,var(--text)_2%,transparent)] px-3 py-2.5 font-mono text-[12px]">
        <div className="min-w-0 flex-1 overflow-x-auto scroll-soft">
          <span className="mr-2 select-none font-bold text-sky-400">$</span>
          <span className="text-[var(--text)] [overflow-wrap:anywhere]">{command || 'bash'}</span>
        </div>
        {command ? (
          <button
            type="button"
            onClick={handleCopyCommand}
            aria-label="Copy command"
            className="shrink-0 rounded p-1 text-[var(--text-muted)] transition-colors hover:bg-[color-mix(in_srgb,var(--text)_8%,transparent)] hover:text-[var(--text)]"
          >
            {copied ? (
              <Check size={12} className="text-emerald-400" />
            ) : (
              <Copy size={12} strokeWidth={1.5} />
            )}
          </button>
        ) : null}
      </div>

      {/* Output Drawer */}
      <AnimatePresence initial={false}>
        {expanded && hasOutput ? (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.2, ease: [0.25, 1, 0.5, 1] }}
            className="overflow-hidden border-t border-[var(--border)]"
          >
            <div className="space-y-2 p-3">
              {parsed.stdout ? (
                <div>
                  <div className="mb-1 font-mono text-[10px] uppercase tracking-wider text-[var(--text-muted)]">
                    stdout
                  </div>
                  <pre className="scroll-soft max-h-56 overflow-auto rounded-[8px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_4%,transparent)] p-2.5 font-mono text-[11.5px] leading-relaxed text-[var(--text)]">
                    {parsed.stdout}
                  </pre>
                </div>
              ) : null}
              {parsed.stderr ? (
                <div>
                  <div className="mb-1 font-mono text-[10px] uppercase tracking-wider text-rose-400">
                    stderr
                  </div>
                  <pre className="scroll-soft max-h-44 overflow-auto rounded-[8px] border border-rose-500/25 bg-rose-500/5 p-2.5 font-mono text-[11.5px] leading-relaxed text-rose-300">
                    {parsed.stderr}
