              ) : null}
              {!parsed.stdout && !parsed.stderr && outcome.errorText ? (
                <p className="font-mono text-[11.5px] text-rose-400">{outcome.errorText}</p>
              ) : null}
            </div>
          </motion.div>
        ) : null}
      </AnimatePresence>
    </div>
  );
}

