function SandboxDocumentCard({
  item,
  active,
}: {
  item: PairedToolItem;
  active: boolean;
}) {
  const [expanded, setExpanded] = useState(false);
  const [copiedContent, setCopiedContent] = useState(false);
  const outcome = parseToolOutcome(item.resultStep);

  const metaObj =
    typeof outcome.content === 'object' && outcome.content !== null
      ? (outcome.content as Record<string, unknown>)
      : {};

  const rawName =
    typeof metaObj.name === 'string'
      ? metaObj.name
      : typeof item.arguments.filename === 'string'
        ? item.arguments.filename
        : typeof item.arguments.name === 'string'
          ? item.arguments.name
          : typeof item.arguments.path === 'string'
            ? item.arguments.path.split('/').pop() ?? 'document'
            : 'document';

  const format =
    typeof metaObj.format === 'string'
      ? metaObj.format
      : typeof item.arguments.format === 'string'
        ? item.arguments.format
        : rawName.split('.').pop() ?? 'file';

  const sizeBytes = typeof metaObj.size_bytes === 'number' ? metaObj.size_bytes : null;
  const sha256 = typeof metaObj.sha256 === 'string' ? metaObj.sha256 : null;
  const hostPath =
    outcome.artifactRef ?? (typeof metaObj.path === 'string' ? metaObj.path : null);
  const docBody = typeof item.arguments.content === 'string' ? item.arguments.content : null;
  const docTitle = typeof item.arguments.title === 'string' ? item.arguments.title : null;

  const handleDownloadClientSide = () => {
    if (!docBody) return;
    const mime =
      format === 'html'
        ? 'text/html'
        : format === 'csv'
          ? 'text/csv'
          : format === 'markdown'
            ? 'text/markdown'
            : 'text/plain';
    const blob = new Blob([docBody], { type: `${mime};charset=utf-8` });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = rawName.includes('.') ? rawName : `${rawName}.${format === 'markdown' ? 'md' : format}`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleCopyDoc = async () => {
    const target = docBody ?? hostPath ?? rawName;
    try {
      await navigator.clipboard.writeText(target);
      setCopiedContent(true);
      setTimeout(() => setCopiedContent(false), 1800);
    } catch {
      // ignore
    }
  };

  return (
    <div className="w-full min-w-0 overflow-hidden rounded-[14px] border border-[var(--border-strong)] bg-[color-mix(in_srgb,var(--text)_4%,transparent)] p-1 shadow-sm">
      <div className="rounded-[10px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-solid)_80%,transparent)] p-3">
        <div className="flex flex-wrap items-center justify-between gap-2.5">
          <div className="flex items-center gap-3 min-w-0">
            <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-[10px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_7%,transparent)] text-[var(--text)]">
              <FileDown size={17} strokeWidth={1.6} />
            </div>
            <div className="min-w-0">
              <div className="flex items-center gap-2">
                <span className="truncate text-[13px] font-semibold text-[var(--text)]">
                  {docTitle ?? rawName}
                </span>
                <span className="shrink-0 rounded-full bg-[color-mix(in_srgb,var(--text)_9%,transparent)] px-2 py-0.5 font-mono text-[10px] font-semibold uppercase tracking-wider text-[var(--text-muted)]">
                  {format}
                </span>
              </div>
              <div className="mt-0.5 flex flex-wrap items-center gap-2 text-[11px] text-[var(--text-muted)]">
                <span className="font-mono">{rawName}</span>
                {sizeBytes !== null ? (
                  <>
                    <span>·</span>
                    <span className="tabular-nums">{formatBytes(sizeBytes)}</span>
                  </>
                ) : null}
                {sha256 ? (
                  <>
                    <span>·</span>
                    <span className="font-mono text-[10px]" title={`SHA-256: ${sha256}`}>
                      #{sha256.slice(0, 8)}
                    </span>
                  </>
                ) : null}
              </div>
            </div>
          </div>

          <div className="flex items-center gap-1.5 shrink-0">
            <StatusPill
              completed={outcome.completed}
              ok={outcome.ok}
              active={active}
              customLabel={outcome.completed && outcome.ok ? 'Delivered' : undefined}
            />
            {docBody ? (
              <button
                type="button"
                onClick={handleDownloadClientSide}
                className="inline-flex cursor-pointer items-center gap-1 rounded-[7px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_7%,transparent)] px-2.5 py-1 text-[11px] font-medium text-[var(--text)] transition-colors hover:bg-[color-mix(in_srgb,var(--text)_12%,transparent)]"
              >
                <FileDown size={12} strokeWidth={1.75} />
                <span>Save</span>
              </button>
            ) : null}
            <button
              type="button"
              onClick={handleCopyDoc}
              className="inline-flex cursor-pointer items-center gap-1 rounded-[7px] px-2 py-1 text-[11px] font-medium text-[var(--text-muted)] transition-colors hover:bg-[color-mix(in_srgb,var(--text)_8%,transparent)] hover:text-[var(--text)]"
            >
              {copiedContent ? (
                <>
                  <Check size={12} className="text-emerald-400" />
                  <span className="text-emerald-400">Copied</span>
                </>
              ) : (
                <>
                  <Copy size={12} strokeWidth={1.5} />
                  <span>{docBody ? 'Copy' : 'Copy path'}</span>
                </>
              )}
            </button>
            {docBody ? (
              <button
                type="button"
                onClick={() => setExpanded((e) => !e)}
                className="inline-flex cursor-pointer items-center gap-1 rounded-[7px] px-2 py-1 text-[11px] font-medium text-[var(--text-muted)] transition-colors hover:bg-[color-mix(in_srgb,var(--text)_8%,transparent)] hover:text-[var(--text)]"
              >
                <span>{expanded ? 'Hide' : 'Inspect'}</span>
                <ChevronDown
                  size={12}
                  className={`transition-transform duration-200 ${expanded ? 'rotate-180' : ''}`}
                />
              </button>
            ) : null}
          </div>
        </div>

        {expanded && docBody ? (
          <div className="mt-3 border-t border-[var(--border)] pt-2.5">
            <pre className="scroll-soft max-h-56 overflow-auto rounded-[8px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_4%,transparent)] p-3 font-mono text-[11.5px] leading-relaxed text-[var(--text)] whitespace-pre-wrap">
              {docBody}
            </pre>
          </div>
        ) : null}
      </div>
    </div>
  );
}

