  const query =
    typeof item.arguments.query === 'string'
      ? item.arguments.query
      : typeof item.arguments.q === 'string'
        ? item.arguments.q
        : null;
  const urls = Array.isArray(item.arguments.urls)
    ? item.arguments.urls.map(String)
    : typeof item.arguments.url === 'string'
      ? [item.arguments.url]
      : [];

  const outputText =
    typeof outcome.content === 'string'
      ? outcome.content
      : outcome.content
        ? JSON.stringify(outcome.content, null, 2)
        : '';

  return (
    <div className="w-full min-w-0 overflow-hidden rounded-[12px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_2.5%,transparent)] p-3">
      <div className="flex items-center justify-between gap-2">
        <div className="flex items-center gap-2 min-w-0">
          <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-[7px] bg-purple-500/12 text-purple-400">
            <Globe size={13} strokeWidth={1.75} />
          </span>
          <span className="shrink-0 text-[12px] font-semibold text-[var(--text)]">
            {item.toolName.includes('fetch') || item.toolName.includes('contents')
              ? 'Web Extract'
              : 'Web Search'}
          </span>
          {query ? (
            <span className="truncate text-[12px] text-[var(--text-muted)]" title={query}>
              “{query}”
            </span>
          ) : urls.length > 0 ? (
            <span className="truncate font-mono text-[11px] text-[var(--text-muted)]">
              {urls[0]} {urls.length > 1 ? `(+${urls.length - 1})` : ''}
            </span>
          ) : null}
        </div>

        <div className="flex items-center gap-2 shrink-0">
          <StatusPill completed={outcome.completed} ok={outcome.ok} active={active} />
          {outputText ? (
            <button
              type="button"
              onClick={() => setExpanded((e) => !e)}
              className="inline-flex cursor-pointer items-center gap-1 rounded-[6px] px-2 py-0.5 text-[11px] font-medium text-[var(--text-muted)] transition-colors hover:bg-[color-mix(in_srgb,var(--text)_8%,transparent)] hover:text-[var(--text)]"
            >
              <span>{expanded ? 'Hide' : 'Results'}</span>
              <ChevronDown
                size={12}
                className={`transition-transform duration-200 ${expanded ? 'rotate-180' : ''}`}
              />
            </button>
          ) : null}
        </div>
      </div>

      {expanded && outputText ? (
        <div className="mt-2.5 border-t border-[var(--border)] pt-2.5">
          <pre className="scroll-soft max-h-52 overflow-auto rounded-[8px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_4%,transparent)] p-2.5 font-mono text-[11px] leading-relaxed text-[var(--text-muted)] whitespace-pre-wrap [overflow-wrap:anywhere]">
            {outputText}
          </pre>
        </div>
      ) : null}
    </div>
  );
}

function GenericToolCard({
  item,
  active,
}: {
  item: PairedToolItem;
  active: boolean;
}) {
  const [expanded, setExpanded] = useState(false);
  const outcome = parseToolOutcome(item.resultStep);

  const getBadgeMeta = (name: string) => {
    if (name === 'skill_load') {
      return {
        icon: <Puzzle size={13} strokeWidth={1.75} />,
        color: 'bg-indigo-500/12 text-indigo-400',
        label: `Skill: ${String(item.arguments.name ?? 'load')}`,
      };
    }
    if (name === 'manage_tasks') {
      return {
        icon: <ListChecks size={13} strokeWidth={1.75} />,
        color: 'bg-teal-500/12 text-teal-400',
        label: `Tasks (${String(item.arguments.operation ?? 'update')})`,
      };
    }
    if (name === 'ask_user') {
      return {
        icon: <HelpCircle size={13} strokeWidth={1.75} />,
        color: 'bg-amber-500/12 text-amber-400',
        label: `Question: ${String(item.arguments.question ?? '')}`,
      };
    }
    if (name.startsWith('gmail')) {
      return {
        icon: <Mail size={13} strokeWidth={1.75} />,
        color: 'bg-sky-500/12 text-sky-400',
        label: name.replace(/_/g, ' '),
      };
    }
    if (name.startsWith('calendar')) {
      return {
        icon: <Calendar size={13} strokeWidth={1.75} />,
        color: 'bg-emerald-500/12 text-emerald-400',
        label: name.replace(/_/g, ' '),
      };
    }
    return {
      icon: <FileText size={13} strokeWidth={1.75} />,
      color: 'bg-[color-mix(in_srgb,var(--text)_8%,transparent)] text-[var(--text)]',
      label: name,
    };
  };

  const meta = getBadgeMeta(item.toolName);
  const hasArgs = Object.keys(item.arguments).length > 0;
  const hasResult = outcome.completed && outcome.rawResult !== null;

  return (
    <div className="w-full min-w-0 overflow-hidden rounded-[12px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_2.5%,transparent)] p-3">
      <div className="flex items-center justify-between gap-2">
        <div className="flex items-center gap-2 min-w-0">
          <span className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-[7px] ${meta.color}`}>
            {meta.icon}
          </span>
          <span className="truncate text-[12px] font-semibold text-[var(--text)]">
            {meta.label}
          </span>
        </div>

        <div className="flex items-center gap-2 shrink-0">
          <StatusPill completed={outcome.completed} ok={outcome.ok} active={active} />
          {hasArgs || hasResult ? (
            <button
              type="button"
              onClick={() => setExpanded((e) => !e)}
              className="inline-flex cursor-pointer items-center gap-1 rounded-[6px] px-2 py-0.5 text-[11px] font-medium text-[var(--text-muted)] transition-colors hover:bg-[color-mix(in_srgb,var(--text)_8%,transparent)] hover:text-[var(--text)]"
            >
              <span>{expanded ? 'Hide' : 'Inspect'}</span>
              <ChevronDown
                size={12}
                className={`transition-transform duration-200 ${expanded ? 'rotate-180' : ''}`}
              />
            </button>
          ) : null}
        </div>
      </div>

      {expanded ? (
        <div className="mt-2.5 space-y-2 border-t border-[var(--border)] pt-2.5 font-mono text-[11px]">
          {hasArgs ? (
            <div>
              <div className="mb-1 text-[10px] uppercase tracking-wider text-[var(--text-muted)]">
                Arguments
              </div>
              <pre className="scroll-soft max-h-40 overflow-auto rounded-[7px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_4%,transparent)] p-2 text-[var(--text-muted)]">
                {JSON.stringify(item.arguments, null, 2)}
              </pre>
            </div>
          ) : null}
          {hasResult ? (
            <div>
              <div className="mb-1 text-[10px] uppercase tracking-wider text-[var(--text-muted)]">
                Output
              </div>
              <pre className="scroll-soft max-h-44 overflow-auto rounded-[7px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_4%,transparent)] p-2 text-[var(--text)]">
                {typeof outcome.content === 'string'
                  ? outcome.content
                  : JSON.stringify(outcome.rawResult, null, 2)}
              </pre>
            </div>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

function renderTimelineItem(item: TimelineItem, active: boolean) {
  if (item.kind === 'thought') {
    return <ReasoningCard step={item.step} />;
  }

  if (item.kind === 'approval_required') {
    return (
      <div className="flex items-center gap-2.5 rounded-[12px] border border-amber-500/30 bg-amber-500/10 px-3.5 py-2.5 text-[12px] text-amber-200">
        <ShieldAlert size={15} className="shrink-0 text-amber-400" />
        <span>Waiting on your approval to execute external action</span>
      </div>
    );
  }

  if (item.kind === 'compaction') {
    return (
      <div className="flex items-center gap-2.5 rounded-[12px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_3%,transparent)] px-3.5 py-2 text-[11.5px] text-[var(--text-muted)]">
        <Archive size={14} className="shrink-0" />
        <span>Context history compacted to preserve token budget</span>
      </div>
    );
  }

  const { toolName } = item;
  if (toolName === 'bash') {
    return <CommandExecutionCard item={item} active={active} />;
  }
  if (toolName === 'read' || toolName === 'write' || toolName === 'edit') {
    return <FileOperationCard item={item} active={active} />;
  }
  if (toolName === 'deliver_file' || toolName === 'generate_document') {
    return <SandboxDocumentCard item={item} active={active} />;
  }
  if (
    toolName === 'web_search' ||
    toolName === 'web_fetch' ||
    toolName.startsWith('exa_') ||
    toolName.includes('search')
  ) {
    return <WebSearchCard item={item} active={active} />;
  }

  return <GenericToolCard item={item} active={active} />;
}

export function ThinkingCapsule({ active, steps = [], summary, defaultOpen }: Props) {
  const items = useMemo(() => buildTimeline(steps), [steps]);
  const [open, setOpen] = useState<boolean>(defaultOpen ?? active);

  if (!active && items.length === 0) return null;

  const toolCount = items.filter((i) => i.kind === 'tool').length;
  const thoughtCount = items.filter((i) => i.kind === 'thought').length;
  const deliveredDocs = items.filter(
    (i): i is PairedToolItem =>
      i.kind === 'tool' &&
      (i.toolName === 'deliver_file' || i.toolName === 'generate_document') &&
      Boolean(i.resultStep),
  );

  const latestItem = items[items.length - 1];

  let displaySummary = summary;
  if (!displaySummary) {
    if (active) {
      if (latestItem?.kind === 'tool' && !latestItem.resultStep) {
        if (latestItem.toolName === 'bash') {
          const cmd =
            typeof latestItem.arguments.command === 'string'
              ? latestItem.arguments.command.slice(0, 38)
              : 'command';
          displaySummary = `Executing $ ${cmd}${cmd.length >= 38 ? '…' : ''}`;
        } else if (
          latestItem.toolName === 'deliver_file' ||
          latestItem.toolName === 'generate_document'
        ) {
          displaySummary = 'Preparing sandbox document...';
        } else {
          displaySummary = `Running ${latestItem.toolName.replace(/_/g, ' ')}...`;
        }
      } else if (latestItem?.kind === 'thought') {
        displaySummary = 'Synthesizing reasoning...';
      } else {
        displaySummary =
          items.length > 0 ? `Working through ${items.length} steps...` : 'Thinking it through...';
      }
    } else {
      const parts: string[] = [];
      if (thoughtCount > 0) parts.push(`${thoughtCount} ${thoughtCount === 1 ? 'thought' : 'thoughts'}`);
      if (toolCount > 0) parts.push(`${toolCount} ${toolCount === 1 ? 'tool call' : 'tool calls'}`);
      displaySummary = parts.length > 0 ? `Processed ${parts.join(' · ')}` : 'Completed reasoning';
    }
  }

  return (
    <div className="my-2 w-full max-w-2xl min-w-0" role="status" aria-live="polite">
      {/* Double-bezel outer shell */}
      <div className="w-full min-w-0 overflow-hidden rounded-[16px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_3%,transparent)] p-1 shadow-sm transition-colors">
        <div className="overflow-hidden rounded-[12px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-solid)_75%,transparent)]">
          {/* Header Bar */}
          <button
            type="button"
            onClick={() => setOpen((o) => !o)}
            aria-expanded={open}
            className="flex w-full cursor-pointer items-center justify-between gap-3 px-3.5 py-2.5 text-left text-[13px] font-medium text-[var(--text)] transition-colors hover:bg-[color-mix(in_srgb,var(--text)_4%,transparent)]"
          >
            <div className="flex items-center gap-2.5 min-w-0">
              <span
                className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full ${
                  active
                    ? 'bg-sky-500/15 text-sky-400'
                    : 'bg-[color-mix(in_srgb,var(--text)_8%,transparent)] text-amber-400'
                }`}
              >
                {active ? (
                  <RotateCw size={13} strokeWidth={2} className="animate-spin" />
                ) : (
                  <Sparkles size={13} strokeWidth={1.75} />
                )}
              </span>

              <span className="truncate font-medium text-[var(--text)]">{displaySummary}</span>

              {items.length > 0 ? (
                <span className="shrink-0 rounded-full border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_5%,transparent)] px-2 py-0.5 font-mono text-[10px] tabular-nums text-[var(--text-muted)]">
                  {items.length} {items.length === 1 ? 'card' : 'cards'}
                </span>
              ) : null}
            </div>

            {items.length > 0 ? (
              <motion.span
                animate={{ rotate: open ? 180 : 0 }}
                transition={spring}
                className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-[var(--text-muted)]"
              >
                <ChevronDown size={14} strokeWidth={1.75} />
              </motion.span>
            ) : null}
          </button>

          {/* Expandable Vertical Card Deck */}
          <AnimatePresence initial={false}>
            {open && items.length > 0 ? (
              <motion.div
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: 'auto', opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                transition={{ duration: 0.24, ease: [0.25, 1, 0.5, 1] }}
                className="overflow-hidden border-t border-[var(--border)]"
              >
                <div className="relative p-3 sm:p-3.5">
                  {/* Subtle connecting vertical rail */}
                  {items.length > 1 ? (
                    <span
                      aria-hidden="true"
                      className="pointer-events-none absolute bottom-6 left-[27px] top-6 w-px bg-[var(--border)]"
                    />
                  ) : null}

                  <ul className="relative space-y-2.5">
                    {items.map((item) => (
                      <li key={item.id} className="relative min-w-0">
                        {renderTimelineItem(item, active)}
                      </li>
                    ))}
                  </ul>
                </div>
              </motion.div>
            ) : null}
          </AnimatePresence>
        </div>
      </div>

      {/* When the deck is collapsed, still surface any delivered sandbox documents prominently */}
      {!open && deliveredDocs.length > 0 ? (
        <div className="mt-2 space-y-2">
          {deliveredDocs.map((doc) => (
            <SandboxDocumentCard key={`Pinned-${doc.id}`} item={doc} active={false} />
          ))}
        </div>
      ) : null}
    </div>
  );
}

export default ThinkingCapsule;

import type { HTMLAttributes, ReactNode } from 'react';
import { cn } from '@/lib/utils';

export type BubbleVariant = 'default' | 'muted';

/*
 * User messages sit inside a tactile double-bezel pill with a tighter bottom-right
 * corner. Assistant replies are rendered unboxed on the editorial canvas, while
 * the muted variant remains available for compact system/fallback surfaces.
 */
const variants: Record<BubbleVariant, string> = {
  default:
    'rounded-[22px] rounded-br-[6px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_10%,transparent)] shadow-xs',
  muted:
    'rounded-[20px] rounded-tl-[6px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_5%,transparent)]',
};

interface BubbleProps extends HTMLAttributes<HTMLDivElement> {
  variant?: BubbleVariant;
  children?: ReactNode;
}

export function Bubble({ variant = 'default', className, children, ...props }: BubbleProps) {
  return (
    <div
      className={cn(
        variants[variant],
        'min-w-0 max-w-full px-4 py-3 text-[15px] leading-[1.65] text-[var(--text)]',
        className,
      )}
      {...props}
    >
      {children}
    </div>
  );
}

/**
 * Content wrapper inside a bubble: enforces word/identifier wrapping without
 * applying whitespace-pre-wrap globally (which breaks parsed Markdown block layouts).
 */
export function BubbleContent({ className, children, ...props }: HTMLAttributes<HTMLDivElement>) {
  return (
    <div className={cn('min-w-0 max-w-full [overflow-wrap:anywhere]', className)} {...props}>
      {children}
    </div>
  );
}

import { useState } from 'react';
import { motion, useReducedMotion } from 'framer-motion';
import { AlertCircle, Check, Copy, Sparkles, Clock } from 'lucide-react';
import type { StreamMessage } from '@/types';
import { Message } from '@/components/ui/c-message-3-utils/message';
import { Bubble, BubbleContent } from '@/components/ui/c-message-3-utils/bubble';
import { MarkdownContent } from './MarkdownContent';
import { ThinkingCapsule } from './ThinkingCapsule';
import { useRunSteps } from '@/queries/runs';

interface Props {
  message: StreamMessage;
  /** Set when this message opens a new day, rendered as a labelled divider. */
  divider?: string;
  /**
   * 0 keeps the entry instant; N staggers the pop, so a thread opened from
   * cold bounces in sequence instead of landing as one slab.
   */
  staggerIndex?: number;
}

const metaTime = (iso: string): string =>
  new Date(iso).toLocaleTimeString(undefined, {
    hour: 'numeric',
    minute: '2-digit',
  });

const enterSpring = {
  type: 'spring' as const,
  stiffness: 420,
  damping: 26,
  mass: 0.9,
};

/** Inline 4-point Vigil spark SVG mark (zero emoji, crisp at 14px). */
export function VigilSpark({ className = '' }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="currentColor"
      aria-hidden="true"
      className={`h-3.5 w-3.5 shrink-0 ${className}`}
    >
      <path d="M8 1C8.55 4.6 11.4 7.45 15 8C11.4 8.55 8.55 11.4 8 15C7.45 11.4 4.6 8.55 1 8C4.6 7.45 7.45 4.6 8 1Z" />
    </svg>
  );
}

export function MessageItem({ message, divider, staggerIndex = 0 }: Props) {
  const mine = message.role === 'user';
  const time = metaTime(message.created_at);
  const reduced = useReducedMotion();
  const delay = staggerIndex * 0.05;

  const [copied, setCopied] = useState(false);
  const [showTrace, setShowTrace] = useState(false);

  // Fetch steps when run_id exists so the thinking deck can be inspected or pinned docs shown
  const runStepsQuery = useRunSteps(message.run_id ? message.run_id : null);
  const mappedSteps = (runStepsQuery.data ?? [])
    .filter((s) => s.event_type !== 'message_delta')
    .map((s) => ({
      run_id: s.run_id,
      step_number: s.step_number,
      event_type: s.event_type,
      payload: s.payload,
      created_at: s.created_at,
    }));

  const hasSemanticSteps = mappedSteps.some(
    (s) => s.event_type !== 'run_completed' && s.event_type !== 'run_failed',
  );

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(message.content);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      const textarea = document.createElement('textarea');
      textarea.value = message.content;
      document.body.appendChild(textarea);
      textarea.select();
      document.execCommand('copy');
      document.body.removeChild(textarea);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <motion.div
      initial={reduced ? { opacity: 0 } : { opacity: 0, y: 14 }}
      animate={{ opacity: 1, y: 0 }}
      transition={reduced ? { duration: 0.2 } : { ...enterSpring, delay }}
      className="w-full max-w-full min-w-0 space-y-2"
    >
      {divider ? <Divider label={divider} /> : null}

      {mine ? (
        /* ── USER MESSAGE: Tactile right-aligned pill ────────────────────── */
        <Message align="end" className="min-w-0 max-w-full">
          <div className="group flex min-w-0 max-w-[85%] flex-col items-end gap-1 sm:max-w-[76%]">
            <motion.div
              initial={reduced ? {} : { scale: 0.94 }}
              animate={{ scale: 1 }}
              transition={reduced ? { duration: 0.2 } : { ...enterSpring, delay: delay + 0.03 }}
              className="min-w-0 max-w-full"
              style={{ transformOrigin: 'bottom right' }}
            >
              <Bubble variant="default">
                <BubbleContent>
                  <span className="block whitespace-pre-wrap [overflow-wrap:anywhere]">
                    {message.content}
                  </span>
                </BubbleContent>
              </Bubble>
            </motion.div>

            {message.local_state === 'failed' && message.failure_reason ? (
              <div className="mt-1 flex items-center gap-1.5 text-[12px] text-rose-400">
                <AlertCircle size={13} strokeWidth={1.75} className="shrink-0" />
                <span className="[overflow-wrap:anywhere]">{message.failure_reason}</span>
              </div>
            ) : null}

            <div className="flex items-center gap-2 px-1 text-[11px] text-[var(--text-muted)] opacity-0 transition-opacity duration-200 group-hover:opacity-100 focus-within:opacity-100">
              {message.local_state === 'sending' ? (
                <span className="inline-flex items-center gap-1">
                  <Clock size={11} strokeWidth={1.5} />
                  Sending
                </span>
              ) : (
                <span className="tabular-nums">{time}</span>
              )}
              <span>·</span>
              <button
                type="button"
                onClick={handleCopy}
                aria-label={copied ? 'Copied message' : 'Copy message'}
                className="inline-flex cursor-pointer items-center gap-1 rounded-[5px] px-1.5 py-0.5 font-medium text-[var(--text-muted)] transition-colors hover:bg-[color-mix(in_srgb,var(--text)_8%,transparent)] hover:text-[var(--text)]"
              >
                {copied ? (
                  <>
                    <Check size={11} strokeWidth={2} className="text-emerald-400" />
                    <span className="text-emerald-400">Copied</span>
                  </>
                ) : (
                  <>
                    <Copy size={11} strokeWidth={1.5} />
                    <span>Copy</span>
                  </>
                )}
              </button>
            </div>
          </div>
        </Message>
      ) : (
        /* ── VIGIL REPLY: Unboxed editorial typography + thinking deck ──── */
        <Message align="start" className="min-w-0 max-w-full">
          <div className="group flex w-full max-w-full min-w-0 flex-col items-start">
            {/* Editorial Header */}
            <div className="mb-2 flex w-full items-center justify-between gap-2">
              <div className="flex items-center gap-2">
                <span className="flex h-5 w-5 items-center justify-center rounded-full bg-[color-mix(in_srgb,var(--text)_9%,transparent)] text-[var(--text)]">
                  <VigilSpark />
                </span>
                <span className="text-[13px] font-semibold tracking-[-0.01em] text-[var(--text)]">
                  Vigil
                </span>
                <span className="text-[11px] font-medium tabular-nums text-[var(--text-muted)] opacity-0 transition-opacity duration-200 group-hover:opacity-100">
                  {time}
                </span>
              </div>

              {message.run_id && hasSemanticSteps ? (
                <button
                  type="button"
                  onClick={() => setShowTrace((t) => !t)}
                  className={`inline-flex cursor-pointer items-center gap-1.5 rounded-full border px-2.5 py-0.5 text-[11px] font-medium transition-colors ${
                    showTrace
                      ? 'border-[var(--border-strong)] bg-[color-mix(in_srgb,var(--text)_9%,transparent)] text-[var(--text)]'
                      : 'border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_3%,transparent)] text-[var(--text-muted)] hover:text-[var(--text)]'
                  }`}
                >
                  <Sparkles size={11} className="text-amber-400" />
                  <span>{showTrace ? 'Hide process' : 'Thinking process'}</span>
                </button>
              ) : null}
            </div>

            {/* Thinking Deck (either toggled open or showing delivered sandbox documents) */}
            {message.run_id && (showTrace || hasSemanticSteps) ? (
              <div className="mb-2 w-full max-w-full min-w-0 pl-0 sm:pl-7">
                {showTrace ? (
                  <ThinkingCapsule
                    active={runStepsQuery.isLoading}
                    steps={mappedSteps}
                    defaultOpen
                  />
                ) : (
                  <ThinkingCapsule
