import { useEffect, useMemo, useRef } from 'react';
import { motion } from 'framer-motion';
import type { ReactNode } from 'react';
import type { StreamMessage } from '@/types';
import MessageItem, { VigilSpark } from './MessageItem';
import { MarkdownContent } from './MarkdownContent';
import { Message } from '@/components/ui/c-message-3-utils/message';

const enterSpring = {
  type: 'spring' as const,
  stiffness: 420,
  damping: 26,
  mass: 0.9,
};

interface Props {
  messages: StreamMessage[];
  streamedText: string;
  streaming: boolean;
  trailing?: ReactNode;
  emptyHint: ReactNode;
}

const STICK_THRESHOLD = 80;

function dayLabel(iso: string): string {
  const d = new Date(iso);
  return d.toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' });
}

export function MessageStream({ messages, streamedText, streaming, trailing, emptyHint }: Props) {
  const endRef = useRef<HTMLDivElement>(null);
  const scrollerRef = useRef<HTMLDivElement>(null);
  const stickRef = useRef(true);

  const seenRef = useRef<Set<string>>(new Set());
  const staggers = useMemo(() => {
    const coldStart = seenRef.current.size === 0;
    return messages.map((m, i) => {
      const fresh = !seenRef.current.has(m.id);
      seenRef.current.add(m.id);
      return fresh && coldStart && i < 8 ? i : 0;
    });
  }, [messages]);

  const dividers = useMemo(() => {
    const out: (string | undefined)[] = [];
    let previous: string | null = null;
    for (const m of messages) {
      const day = dayLabel(m.created_at);
      out.push(day !== previous ? day : undefined);
      previous = day;
    }
    return out;
  }, [messages]);

  useEffect(() => {
    const node = scrollerRef.current;
    if (!node) return;
    const onScroll = () => {
      stickRef.current = node.scrollHeight - node.scrollTop - node.clientHeight < STICK_THRESHOLD;
    };
    node.addEventListener('scroll', onScroll, { passive: true });
    return () => node.removeEventListener('scroll', onScroll);
  }, []);

  useEffect(() => {
    if (!stickRef.current) return;
    endRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' });
  }, [messages.length, streamedText, streaming]);

  const isEmpty = messages.length === 0 && !streaming;

  return (
    <div ref={scrollerRef} className="scroll-soft h-full w-full overflow-x-hidden overflow-y-auto">
      <div className="mx-auto w-full max-w-3xl min-w-0 space-y-8 px-4 pb-52 pt-24 sm:px-6 md:pl-24 md:pr-8 md:pt-28">
        {isEmpty ? emptyHint : null}

        <ul
          className="w-full max-w-full min-w-0 space-y-8"
          aria-live="polite"
          aria-relevant="additions text"
          aria-busy={streaming}
        >
          {messages.map((message, i) => (
            <li key={message.id} className="group w-full max-w-full min-w-0">
              <MessageItem message={message} divider={dividers[i]} staggerIndex={staggers[i]} />
            </li>
          ))}

          {/* Active turn: Thinking deck + live editorial markdown stream */}
          {streaming && (trailing || streamedText) ? (
            <li className="w-full max-w-full min-w-0">
              <motion.div
                initial={{ opacity: 0, y: 14 }}
                animate={{ opacity: 1, y: 0 }}
                transition={enterSpring}
                className="w-full max-w-full min-w-0"
              >
                <Message align="start" className="min-w-0 max-w-full">
                  <div className="flex w-full max-w-full min-w-0 flex-col items-start">
                    <div className="mb-2 flex items-center gap-2">
                      <span className="flex h-5 w-5 items-center justify-center rounded-full bg-[color-mix(in_srgb,var(--text)_9%,transparent)] text-[var(--text)]">
                        <VigilSpark className="animate-pulse" />
                      </span>
                      <span className="text-[13px] font-semibold tracking-[-0.01em] text-[var(--text)]">
                        Vigil
                      </span>
                      <span className="rounded-full bg-[color-mix(in_srgb,var(--text)_6%,transparent)] px-2 py-0.5 text-[10px] font-medium text-[var(--text-muted)]">
                        Live
                      </span>
                    </div>

                    {trailing ? (
                      <div className="mb-3 w-full max-w-full min-w-0 pl-0 sm:pl-7">
                        {trailing}
                      </div>
                    ) : null}

                    {streamedText ? (
                      <div className="w-full max-w-full min-w-0 pl-0 sm:pl-7">
                        <MarkdownContent content={streamedText} />
                        <span
                          aria-hidden
                          className="mt-1 inline-block h-[1.05em] w-[2px] animate-pulse bg-[var(--text)] align-middle"
                        />
                      </div>
                    ) : null}
                  </div>
                </Message>
              </motion.div>
            </li>
          ) : null}
        </ul>

        <div ref={endRef} />
      </div>
    </div>
  );
}

export default MessageStream;

