1: import { useCallback, useEffect, useRef, useState } from 'react';
2: import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
3: import { api } from '@/lib/api';
4: import { releaseIdempotencyKey } from '@/lib/idempotency';
5: import type { AgentConfigResponse, Run, RunStatus, RunStep, RunStepEvent } from '@/types';
6: 
7: export const runKey = (runId: string) => ['runs', runId] as const;
8: export const runStepsKey = (runId: string) => ['runs', runId, 'steps'] as const;
9: export const RUN_CONFIG_KEY = ['runs', 'default-config'] as const;
10: 
11: /** The pinned server-side default agent config, created on the first call, cached for the
12:  *  session. Every run creator (chat sends, card run actions) keys off the same row. */
13: export function useDefaultAgentConfig() {
14:   return useQuery<AgentConfigResponse>({
15:     queryKey: RUN_CONFIG_KEY,
16:     queryFn: () => api.getDefaultAgentConfig(),
17:     staleTime: Infinity,
18:   });
19: }
20: 
21: const TERMINAL_STATUSES: Run['status'][] = ['completed', 'failed'];
22: 
23: const STEP_LABELS: Record<string, string> = {
24:   thought: 'Thinking',
25:   tool_call: 'Using a tool',
26:   tool_result: 'Tool finished',
27:   approval_required: 'Waiting on you',
28:   run_completed: 'Done',
29:   run_failed: 'Failed',
30: };
31: 
32: /** One line for the ThinkingCapsule-style step list. */
33: export function stepLabel(step: RunStepEvent): string {
34:   const base = STEP_LABELS[step.event_type] ?? step.event_type;
35:   const detail =
36:     step.payload['content'] ?? step.payload['text'] ?? step.payload['tool_name'] ?? step.payload['reason'];
37:   return typeof detail === 'string' && detail.length > 0
38:     ? `${base}: ${detail.length > 90 ? `${detail.slice(0, 90)}...` : detail}`
39:     : base;
40: }
41: 
42: export interface RunSubscription {
43:   run: Run | null;
44:   /** Steps received so far, oldest first, both from fetch and the stream. */
45:   steps: RunStepEvent[];
46:   connection: 'idle' | 'connecting' | 'open' | 'reconnecting' | 'closed';
47: }
48: 
49: /**
50:  * One run's live state: the run row, its steps, and the SSE subscription that keeps both
51:  * current.
52:  *
53:  * Fetches `GET /runs/{id}` once, then opens `GET /runs/{id}/events`. Frames carry the step
54:  * number as the SSE id, so a reconnect replays with `Last-Event-ID` and nothing is missed
55:  * between fetch and stream. A fetched snapshot can race the stream, so every frame is merged
56:  * by `step_number` rather than appended blindly. The subscription closes itself when the
57:  * backend closes the stream, which it does only on terminal statuses.
58:  */
59: export function useRun(runId: string | null): RunSubscription {
60:   const queryClient = useQueryClient();
61: 
62:   const [steps, setSteps] = useState<RunStepEvent[]>([]);
63:   const [connection, setConnection] = useState<RunSubscription['connection']>('idle');
64:   const bufferRef = useRef<RunStepEvent[]>([]);
65:   const streamVersionRef = useRef(0);
66: 
67:   // Merging on every single frame would thrash React. Frames land in a ref buffer and a
68:   // rAF-aligned flush publishes them at most once per frame.
69:   const scheduleFlush = useCallback(() => {
70:     if (bufferRef.current.length === 0) return;
71:     const buffered = bufferRef.current;
72:     bufferRef.current = [];
73:     streamVersionRef.current += 1;
74:     setSteps((current) => mergeSteps(current, buffered));
75:   }, []);
76: 
77:   const runQuery = useQuery<Run>({
78:     queryKey: runKey(runId ?? 'none'),
79:     queryFn: () => api.getRun(runId as string),
80:     enabled: Boolean(runId),
81:   });
82: 
83:   useEffect(() => {
84:     if (!runId) {
85:       bufferRef.current = [];
86:       setSteps([]);
87:       setConnection('idle');
88:       return undefined;
89:     }
90: 
91:     bufferRef.current = [];
92:     setSteps([]);
93:     streamVersionRef.current += 1;
94: 
95:     // Buffered snapshot first: GET /runs/{id}/steps seeds the list, the stream then carries
96:     // only frames past that point.
97:     let cancelled = false;
98:     void api
99:       .getRunSteps(runId)
100:       .then((history: RunStep[]) => {
101:         if (cancelled) return;
102:         setSteps(
103:           history.map((step) => ({
104:             run_id: step.run_id,
105:             step_number: step.step_number,
106:             event_type: step.event_type,
107:             payload: step.payload,
108:             created_at: step.created_at,
109:           })),
110:         );
111:       })
112:       .catch(() => {
113:         // The stream replays from the cursor anyway, an unreachable history is not fatal.
114:       });
115: 
116:     const close = api.openRunStream(runId, {
117:       handlers: {
118:         onEvent(event) {
119:           let parsed: RunStepEvent;
120:           try {
121:             parsed = JSON.parse(event.data) as RunStepEvent;
122:           } catch {
123:             return;
124:           }
125:           // Terminal frames override whatever the payload says, the SSE event name is what
126:           // the backend wrote and the payload mirrors it.
127:           const eventType: RunStepEvent['event_type'] =
128:             event.type === 'run_completed' || event.type === 'run_failed' ? event.type : parsed.event_type;
129:           bufferRef.current = [...bufferRef.current, { ...parsed, event_type: eventType }];
130:           scheduleFlush();
131:         },
132:         onStateChange(state) {
133:           setConnection(state);
134:         },
135:       },
136:     });
137: 
138:     return () => {
139:       cancelled = true;
140:       close();
141:     };
142:   }, [runId, queryClient, scheduleFlush]);
143: 
144:   // The stream carries the terminal step, but the run row was fetched once when the run was
145:   // created (still queued). Without this derivation the finaliser waits on a status that only
146:   // a later refetch would deliver, which made replies appear only after a tab refresh.
147:   useEffect(() => {
148:     if (!runId) return;
149:     const terminal = [...steps].reverse().find((s) => s.event_type === 'run_completed' || s.event_type === 'run_failed');
150:     if (!terminal) return;
151:     queryClient.setQueryData<Run>(runKey(runId), (current) => {
152:       if (!current || TERMINAL_STATUSES.includes(current.status)) return current;
153:       const status: RunStatus = terminal.event_type === 'run_completed' ? 'completed' : 'failed';
154:       return { ...current, status };
155:     });
156:   }, [runId, steps, queryClient]);
157: 
158:   return { run: runQuery.data ?? null, steps, connection };
159: }
160: 
161: /** Merge by step number, deduping re-delivered frames after a reconnect. */
162: function mergeSteps(current: RunStepEvent[], incoming: RunStepEvent[]): RunStepEvent[] {
163:   const byStep = new Map<number, RunStepEvent>();
164:   for (const step of current) byStep.set(step.step_number, step);
165:   for (const step of incoming) {
166:     const existing = byStep.get(step.step_number);
167:     if (!existing || existing.event_type !== step.event_type) byStep.set(step.step_number, step);
168:   }
169:   return [...byStep.values()].sort((a, b) => a.step_number - b.step_number);
170: }
171: 
172: export function useCancelRun() {
173:   const queryClient = useQueryClient();
174: 
175:   return useMutation({
176:     mutationFn: ({ runId, scope }: { runId: string; scope: string }) =>
177:       api.cancelRun(runId, scope),
178: 
179:     onMutate: async ({ runId }) => {
180:       await queryClient.cancelQueries({ queryKey: runKey(runId) });
181:       const previous = queryClient.getQueryData<Run>(runKey(runId));
182:       if (previous && !TERMINAL_STATUSES.includes(previous.status)) {
183:         queryClient.setQueryData<Run>(runKey(runId), { ...previous, status: 'failed' });
184:       }
185:       return { previous };
186:     },
187: 
188:     onError: (_error, variables, context) => {
189:       if (context?.previous) queryClient.setQueryData(runKey(variables.runId), context.previous);
190:     },
191: 
192:     onSuccess: (result) => {
193:       queryClient.setQueryData<Run>(runKey(result.run_id), (current) =>
194:         current ? { ...current, status: (result.status as Run['status']) ?? current.status } : current,
195:       );
196:     },
197: 
198:     onSettled: (_data, _error, variables) => {
199:       releaseIdempotencyKey(variables.scope);
200:       void queryClient.invalidateQueries({ queryKey: runKey(variables.runId) });
201:     },
202:   });
203: }
204: 
205: export function useRunSteps(runId: string | null, sinceStep = 0) {
206:   return useQuery<RunStep[]>({
207:     queryKey: [...runStepsKey(runId ?? 'none'), sinceStep],
208:     queryFn: () => api.getRunSteps(runId as string, sinceStep),
209:     enabled: Boolean(runId),
210:   });
211: }

