1: import type { SseEvent, StreamState } from '@/types';
2: 
3: export interface EventStreamOptions {
4:   url: string;
5:   token: string;
6:   onEvent: (event: SseEvent) => void;
7:   onStateChange?: (state: StreamState) => void;
8:   maxAttempts?: number;
9: }
10: 
11: const BASE_BACKOFF_MS = 500;
12: const MAX_BACKOFF_MS = 15_000;
13: 
14: /**
15:  * Reads a `text/event-stream` response with fetch.
16:  *
17:  * EventSource is deliberately not used: it cannot set an `Authorization` header, and the backend
18:  * accepts only `Authorization: Bearer vgt_...`. Putting the token in the query string would leak
19:  * it into access logs and `Referer`.
20:  *
21:  * Returns a close function. Reconnection is internal, with exponential backoff and
22:  * `Last-Event-ID` replay when the server supplies event ids.
23:  */
24: export function createEventStream(options: EventStreamOptions): () => void {
25:   const maxAttempts = options.maxAttempts ?? 6;
26: 
27:   let closed = false;
28:   let attempt = 0;
29:   let controller: AbortController | null = null;
30:   let retryTimer: ReturnType<typeof setTimeout> | null = null;
31:   let lastEventId: string | undefined;
32: 
33:   const setState = (state: StreamState) => options.onStateChange?.(state);
34: 
35:   const scheduleReconnect = () => {
36:     if (closed) return;
37:     attempt += 1;
38: 
39:     if (attempt > maxAttempts) {
40:       setState('closed');
41:       return;
42:     }
43: 
44:     setState('reconnecting');
45:     const delay = Math.min(MAX_BACKOFF_MS, BASE_BACKOFF_MS * 2 ** (attempt - 1));
46:     retryTimer = setTimeout(() => {
47:       void connect();
48:     }, delay);
49:   };
50: 
51:   const handleFrame = (rawFrame: string) => {
52:     // Normalise CRLF so a proxy that rewrites line endings cannot break parsing.
53:     const frame = rawFrame.replace(/\r\n/g, '\n');
54:     if (frame.trimStart().startsWith(':')) return; // comment / keep-alive
55: 
56:     let type = 'message';
57:     let id: string | undefined;
58:     const dataLines: string[] = [];
59: 
60:     for (const line of frame.split('\n')) {
61:       if (line.startsWith('event:')) {
62:         type = line.slice(6).trim();
63:       } else if (line.startsWith('data:')) {
64:         dataLines.push(line.slice(5).replace(/^ /, ''));
65:       } else if (line.startsWith('id:')) {
66:         id = line.slice(3).trim();
67:       }
68:     }
69: 
70:     if (dataLines.length === 0) return;
71: 
72:     if (id) lastEventId = id;
73:     const event: SseEvent = id
74:       ? { type, data: dataLines.join('\n'), id }
75:       : { type, data: dataLines.join('\n') };
76:     options.onEvent(event);
77:   };
78: 
79:   const connect = async (): Promise<void> => {
80:     if (closed) return;
81: 
82:     controller = new AbortController();
83:     setState(attempt === 0 ? 'connecting' : 'reconnecting');
84: 
85:     const headers: Record<string, string> = {
86:       Accept: 'text/event-stream',
87:       Authorization: `Bearer ${options.token}`,
88:     };
89:     if (lastEventId) headers['Last-Event-ID'] = lastEventId;
90: 
91:     try {
92:       const response = await fetch(options.url, {
93:         headers,
94:         signal: controller.signal,
95:         cache: 'no-store',
96:       });
97: 
98:       if (!response.ok || !response.body) {
99:         throw new Error(`Stream rejected with ${response.status}`);
100:       }
101: 
102:       attempt = 0;
103:       setState('open');
104: 
105:       const reader = response.body.pipeThrough(new TextDecoderStream()).getReader();
106:       let buffer = '';
107: 
108:       for (;;) {
109:         const { value, done } = await reader.read();
110:         if (done) break;
111:         buffer += value;
112: 
113:         let boundary = buffer.indexOf('\n\n');
114:         while (boundary !== -1) {
115:           const frame = buffer.slice(0, boundary);
116:           buffer = buffer.slice(boundary + 2);
117:           handleFrame(frame);
118:           boundary = buffer.indexOf('\n\n');
119:         }
120:       }
121:     } catch (error) {
122:       if (closed) return;
123:       if (error instanceof DOMException && error.name === 'AbortError') return;
124:       // Falls through to reconnect.
125:     }
126: 
127:     if (closed) return;
128:     scheduleReconnect();
129:   };
130: 
131:   void connect();
132: 
133:   return () => {
134:     closed = true;
135:     if (retryTimer) clearTimeout(retryTimer);
136:     controller?.abort();
137:     setState('closed');
138:   };
139: }

