161: /** Merge by step number, deduping re-delivered frames after a reconnect. */
162: function mergeSteps(current: RunStepEvent[], incoming: RunStepEvent[]): RunStepEvent[] {
163:   const byStep = new Map<number, RunStepEvent>();
164:   for (const step of current) byStep.set(step.step_number, step);
165:   for (const step of incoming) {
166:     const existing = byStep.get(step.step_number);
167:     if (!existing || existing.event_type !== step.event_type) byStep.set(step.step_number, step);
168:   }
169:   return [...byStep.values()].sort((a, b) => a.step_number - b.step_number);
170: }
